"""Writes mac.v for a given input width: RTL from a generator.

Stands in for whatever generates your RTL, in whatever language: Bazel
runs it, and a change to it or to its options rebuilds only what it
reaches. --bits 8 writes the same unit as ../mac.v.

    gen_mac.py --bits 8 > mac.v
"""

import argparse
import sys

RTL = """\
// Generated by examples/generated/gen_mac.py --bits {bits}: do not edit.
//
// Multiply-accumulate: acc <= acc + a * b on every enabled clock.
module mac (
    input             clk,
    input             rst,
    input             en,
    input      [{top}:0]  a,
    input      [{top}:0]  b,
    output reg [{acc_top}:0] acc
);

  always @(posedge clk) begin
    if (rst) begin
      acc <= {acc_bits}'d0;
    end else if (en) begin
      acc <= acc + a * b;
    end
  end

endmodule
"""


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--bits", type=int, required=True, help="width of a and b")
    args = ap.parse_args(argv)
    if args.bits < 1:
        ap.error("--bits must be at least 1")
    # Room for the product and 256 accumulations of it.
    acc_bits = 2 * args.bits + 8
    sys.stdout.write(
        RTL.format(
            bits=args.bits, top=args.bits - 1, acc_bits=acc_bits, acc_top=acc_bits - 1
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
